<section class="container page-section"><div class="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/orders">Your orders</a><span>/</span><span><?= e($order['order_number']) ?></span></div><span class="eyebrow">ORDER DETAILS</span><h1>Thanks for your order.</h1><p class="page-intro">Order <?= e($order['order_number']) ?> · Placed <?= e(date('M j, Y',strtotime($order['created_at']))) ?> · Demo status: <?= e($order['status']) ?></p><div class="order-detail-layout"><div class="order-products"><?php foreach($items as $item): ?><div class="cart-item"><div class="cart-item-image"><img src="<?= e($item['image_url']) ?>" alt=""></div><div class="cart-item-info"><strong class="cart-item-name"><?= e($item['product_name']) ?></strong><p class="muted">Quantity: <?= (int)$item['quantity'] ?></p></div><strong><?= money($item['unit_price']*$item['quantity']) ?></strong></div><?php endforeach; ?></div><aside class="order-summary"><h2>Payment summary</h2><div class="summary-line"><span>Subtotal</span><span><?= money($order['subtotal']) ?></span></div><div class="summary-line"><span>Shipping</span><span><?= money($order['shipping']) ?></span></div><div class="summary-line"><span>Tax</span><span><?= money($order['tax']) ?></span></div><div class="summary-total"><span>Total</span><strong><?= money($order['total']) ?></strong></div><p class="tax-note">No payment was collected by this demo.</p><h3>Ship to</h3><p><?= e($order['shipping_name']) ?><br><?= nl2br(e($order['shipping_address'])) ?></p></aside></div><a class="btn btn-outline" href="/products">Continue shopping</a></section>